fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // Split the string by line endings
            let mut lines: Vec<String> = s.split('\n')
                .map(|line| {
                    if keepends {
                        line.to_string() // Keep the line as is
                    } else {
                        line.trim_end().to_string() // Remove the line ending
                    }
                })
                .collect();

            // Ensure that we have at least one element in the inner list
            if lines.is_empty() {
                lines.push(String::new()); // Push an empty string if no lines were found
            }

            lines
        })
        .collect()
}